  ],
  "indicator_readings": [
    {
      "indicator": "MM20",
      "reading": "12.1695",
      "interpretation": "Preço (12,00) ≈1,4% abaixo da MM20 — resistência de curto prazo; curto prazo mostra fraqueza."
    },
    {
      "indicator": "MM50",
      "reading": "11.8882",
      "interpretation": "Preço ≈0,9% acima da MM50 — suporte de médio prazo; estrutura ainda sustentada enquanto acima."
    },
    {
      "indicator": "MM200",
      "reading": "12.5201",
      "interpretation": "Preço ≈4,2% abaixo da MM200 — tendência de longo prazo não confirmada; MM200 é resistência relevante."
    },
    {
      "indicator": "EMA9",
      "reading": "12.0327",
      "interpretation": "EMA9 ligeiramente acima do preço — pullback de curtíssimo prazo."
    },
    {
      "indicator": "EMA21",
      "reading": "12.0845",
      "interpretation": "EMA21 acima do preço e próxima à MM20 — confirma resistência imediata na faixa de R$12,08–12,17."
    },
    {
      "indicator": "MACD (12,26,9)",
      "reading": "MACD 0.0031 / Signal 0.0807 / Hist -0.0776",
      "interpretation": "MACD muito próximo de zero e abaixo da linha de sinal; histograma negativo de baixa magnitude indica perda de momentum comprador, sem reversão clara ainda."
    },
    {
      "indicator": "Bollinger (20,2σ)",
      "reading": "Lower 11.5190 / Mid 12.1695 / Upper 12.8200",
      "interpretation": "Preço entre mid e lower; bandas relativamente comprimidas -> consolidação; lower band (11,5190) atua como suporte técnico."
    },
    {
      "indicator": "RSI14",
      "reading": "48.6773",
      "interpretation": "Neutro (≈50). Sem sobrecompra/sobrevenda; queda desde março indica perda de força."
    },
    {
      "indicator": "Volume",
      "reading": "17592712900",
      "interpretation": "Volume do pregão elevado em relação a muitos dias recentes — confirma maior participação; rompimentos com volume serão mais confiáveis."
    }
  ]
}
